Lemma bdyn_refb (Ma Mb : mem) s fbx fbx' (len len' : nat) q w0 w1 : 0 <= s -> s + 32 <= 2 ^ 64 -> 0 <= q -> q + 64 <= 2 ^ 64 ->
  PQATSW2.bdyn_at RSEGS Ma s fbx len q w0 w1 ->
  L5.u8_at RSEGS Mb s fbx' -> 0 <= fbx' < 256 -> Z.testbit fbx' 0 = true -> L5.u64_at RSEGS Mb (s + 8) (Z.of_nat len') -> (len' <= 2)%nat ->
  (forall a, s + 16 <= a < s + 32 -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a)) -> PMFA.agA Ma Mb q 64 ->
  PQATSW2.bdyn_at RSEGS Mb s fbx' len' q w0 w1.
