(* [comment removed for export] *)
Ltac pf D1 INC BIx :=
  destruct ((GF [D1, INC] PQAKR3F.g_pfacts) _ _ _ _ _ _ BIx) as ((PF1 & PF2 & PF3 & PF4 & _) & (FD & FW & FSW & FLU & FLW) & (PL1 & PL2 & PL3 & PL4) & (SW & OWNV & PS1 & PS2 & PS3 & PS4) & (CSB & CUAR & IMGC) & (AVSH & AVF & AVS));
  change (ff_bytes 2) with 256 in *; change (256 / 8) with 32 in *.

(* [comment removed for export] *)
Definition WPF (a : Z) : Prop := (sp - SCR <= a < sp) \/ (F <= a < F + 256) \/ (F / 8 + SB <= a < F / 8 + SB + 32).

