Lemma GEK Dy (INCy : incl D Dy) BX1 M1 model1 LK1 Aw1 cr1 (M3 : mem) (Wp : Z -> Prop) :
  GM [Dy] BX1 M1 model1 LK1 Aw1 cr1 ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ Wp a -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) -> (forall a, Wp a -> WPF a) ->
