Lemma vstr_long_keep (M1 M3 : mem) o' c n p (Wq : Z -> Prop) :
  0 <= o' -> o' + 24 <= 2 ^ 47 -> 0 <= p -> p + c <= 2 ^ 47 ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ Wq a -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) -> mem_grows M1 M3 ->
  (forall a, Wq a -> p <= a < p + 32) -> (p + 32 <= o' \/ o' + 24 <= p) -> (2147446784 + 17592186048512 <= p \/ p + 32 <= 2147446784) ->
