Lemma L_T Dy (INCy : incl D Dy) My modely LKy Awy cry (c n p fbr fbv : Z) (fx5 : FPState) R5 :
  GM [Dy] [(p, c); (pv, 64)] My modely LKy Awy cry -> vstr_at My ot (PM.VLong c n p) -> 1 <= n <= 30 -> PQATSW2.ws2_postL x (PM.VLong c n p) -> strC My p n ->
  ACT Dy cry (POT (PM.VLong c n p)) 1 ->
  REGSP R5 -> getr R5 (reg 19) = Z_to_bv 64 (F / 8 + 2147450880) -> getr R5 (reg 21) = Z_to_bv 64 (F + 96) -> getr R5 (reg 22) = Z_to_bv 64 F ->
  getr R5 (reg 23) = Z_to_bv 64 F -> getr R5 (reg 24) = Z_to_bv 64 (F + 32) ->
  L5.u8_at RSEGS My (spc + 88) 0 ->
  L5.u8_at RSEGS My (F + 96) fbr -> 0 <= fbr <= 255 -> Z.testbit fbr 0 = false ->
  L5.u8_at RSEGS My (F + 32) fbv -> 0 <= fbv <= 255 -> Z.testbit fbv 0 = true ->
  L5.u64_at RSEGS My (F + 48) 8 -> L5.u64_at RSEGS My (F + 56) pv ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx5 R5 TAILPC My modely) K.
Proof.
