Lemma DSTEP Dy (INCy : incl D Dy) My modely LKy Awy cry (c n p rv j : Z) (fx5 : FPState) R5 :
  GM [Dy] [(p, c); (pv, 64)] My modely LKy Awy cry -> vstr_at My ot (PM.VLong c n p) -> 32 <= c -> 0 <= n <= 29 -> strC My p n ->
  REGSP R5 -> getr R5 (reg 10) = Z_to_bv 64 j -> getr R5 (reg 18) = Z_to_bv 64 10 -> getr R5 (reg 22) = Z_to_bv 64 M10 -> getr R5 (reg 24) = Z_to_bv 64 rv ->
  0 <= j <= 18 -> 0 <= rv < 2 ^ 64 ->
  (forall (fx8 : FPState) R8 M8 model8 LK8,
      GM [Dy] [(p, c); (pv, 64)] M8 model8 LK8 Awy cry -> vstr_at M8 ot (PM.VLong c (n + 1) p) -> strC M8 p (n + 1) -> REGSP R8 ->
      (forall k, In k [18; 21; 22; 23; 25; 26; 27]%nat -> getr R8 (reg k) = getr R5 (reg k)) ->
      getr R8 (reg 19) = Z_to_bv 64 j -> getr R8 (reg 24) = Z_to_bv 64 (rv / 10) ->
      (forall a, spc <= a < sp -> M8 (Z_to_bv 64 a) = My (Z_to_bv 64 a)) ->
      (forall a, F + 32 <= a < F + 128 -> M8 (Z_to_bv 64 a) = My (Z_to_bv 64 a)) ->
      (forall a, F / 8 + SB <= a < F / 8 + SB + 32 -> M8 (Z_to_bv 64 a) = My (Z_to_bv 64 a)) -> PMFA.agA My M8 pv 64 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx8 R8 RA_PBD M8 model8) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx5 R5 DIGIT My modely) K.
Proof.
