Lemma DLOOP1 (mn : nat) : forall Dy (INCy : incl D Dy) My modely LKy Awy cry (Mb : mem) (c p rv j : Z) (fx5 : FPState) R5,
  18 - j < Z.of_nat mn ->
  GM [Dy] [(p, c); (pv, 64)] My modely LKy Awy cry -> vstr_at My ot (PM.VLong c j p) -> strC My p j -> 32 <= c -> AGR Mb My ->
  REGSP R5 -> getr R5 (reg 10) = Z_to_bv 64 j -> getr R5 (reg 18) = Z_to_bv 64 10 -> getr R5 (reg 21) = Z_to_bv 64 (F + 96) -> getr R5 (reg 22) = Z_to_bv 64 M10 ->
  getr R5 (reg 23) = Z_to_bv 64 (F + 104) -> getr R5 (reg 24) = Z_to_bv 64 rv -> getr R5 (reg 25) = Z_to_bv 64 18 -> getr R5 (reg 26) = Z_to_bv 64 18446744073709551615 -> getr R5 (reg 27) = Z_to_bv 64 1 ->
  0 <= j <= 18 -> 0 <= rv < 2 ^ 64 ->
  (forall (fx8 : FPState) R8 M8 model8 LK8 (rv' : Z),
      GM [Dy] [(p, c); (pv, 64)] M8 model8 LK8 Awy cry -> vstr_at M8 ot (PM.VLong c 19 p) -> strC M8 p 19 -> AGR Mb M8 -> REGSP R8 ->
      getr R8 (reg 18) = Z_to_bv 64 10 -> getr R8 (reg 19) = Z_to_bv 64 18 -> getr R8 (reg 21) = Z_to_bv 64 (F + 96) -> getr R8 (reg 22) = Z_to_bv 64 M10 ->
      getr R8 (reg 23) = Z_to_bv 64 (F + 104) -> getr R8 (reg 24) = Z_to_bv 64 rv' -> 0 <= rv' <= 18446744073709551614 -> getr R8 (reg 25) = Z_to_bv 64 18 ->
      getr R8 (reg 26) = Z_to_bv 64 18446744073709551615 -> getr R8 (reg 27) = Z_to_bv 64 1 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx8 R8 RA_PBD M8 model8) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx5 R5 DIGIT My modely) K.
Proof.
