Lemma shadow_zero_sub (Mx : mem) lo g lo' g' : shadow_zero Mx lo g -> lo mod 8 = 0 -> lo' mod 8 = 0 -> 0 <= lo -> lo <= lo' -> 0 <= g' -> lo' + 8 * g' <= lo + 8 * g -> shadow_zero Mx lo' g'.
