(* [comment removed for export] *)
(* [comment removed for export] *)
Lemma DIVC2 Dy (INCy : incl D Dy) My modely LKy Awy cry (c n p fbv w0 w1 fbr : Z) (rl : nat) (r0 r1 : Z) (fx5 : FPState) R5 :
  GM [Dy] [(p, c); (pv, 64)] My modely LKy Awy cry -> vstr_at My ot (PM.VLong c n p) -> strC My p n -> FRAM My -> VRF My fbv 2%nat w0 w1 fbr rl r0 r1 -> 1 <= w1 <= 2 ^ 30 -> (rl <= 1)%nat ->
  ACT Dy cry (POT (PM.VLong c n p)) 1 ->
  getr R5 (reg 1) = Z_to_bv 64 RA_DIV -> REGSP R5 ->
  getr R5 (reg 10) = Z_to_bv 64 (F + 32) -> getr R5 (reg 11) = Z_to_bv 64 (spc + 88) -> getr R5 (reg 12) = Z_to_bv 64 (F + 32) -> getr R5 (reg 13) = Z_to_bv 64 (F + 96) ->
  getr R5 (reg 14) = Z_to_bv 64 1 ->
  (forall (fx8 : FPState) R8 M8 model8 LK8 Aw8 cr8 D8 (INC8 : incl D D8) (fbq fbr' : Z),
      GM [D8] [(p, c); (pv, 64)] M8 model8 LK8 Aw8 cr8 -> vstr_at M8 ot (PM.VLong c n p) -> strC M8 p n -> FRAM M8 ->
      VRF M8 fbq 1%nat ((w0 + 2 ^ 64 * w1) / TEN19) w1 fbr' (PQATSS.wlen ((w0 + 2 ^ 64 * w1) mod TEN19) 0) ((w0 + 2 ^ 64 * w1) mod TEN19) 0 ->
      ACT D8 cr8 (POT (PM.VLong c n p)) 1 ->
      regs_preserved R5 R8 -> REGSP R8 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx8 R8 RA_DIV M8 model8) K) ->
